<?php if ($canWrite): ?><div class="management-grid"><details class="card form-card" <?= $error && ($_POST['action'] ?? '')==='course' ? 'open' : '' ?>><summary>+ Planifier un cours</summary><form method="post" action="index.php?page=courses" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="course"><label>Nom du cours *<input name="title" maxlength="120" required value="<?= e(($_POST['action'] ?? '')==='course' && is_string($_POST['title'] ?? null) ? $_POST['title'] : '') ?>"></label><label>Salle *<select name="room_id" required><option value="">Sélectionner</option><?php foreach ($rooms as $r): ?><option value="<?= (int)$r['id'] ?>" <?= (string)$r['id']===($_POST['room_id'] ?? '') ? 'selected' : '' ?>><?= e($r['name']) ?></option><?php endforeach; ?></select></label><label>Coach<select name="coach_id"><option value="">Non attribué</option><?php foreach ($coaches as $coach): ?><option value="<?= (int)$coach['id'] ?>" <?= (string)$coach['id']===($_POST['coach_id'] ?? '') ? 'selected' : '' ?>><?= e($coach['name']) ?></option><?php endforeach; ?></select></label><label>Capacité *<input type="number" name="capacity" min="1" max="1000" required value="<?= e(is_string($_POST['capacity'] ?? null) ? $_POST['capacity'] : '') ?>"></label><label>Début *<input type="datetime-local" name="starts_at" required value="<?= e(is_string($_POST['starts_at'] ?? null) ? $_POST['starts_at'] : '') ?>"></label><label>Fin *<input type="datetime-local" name="ends_at" required value="<?= e(is_string($_POST['ends_at'] ?? null) ? $_POST['ends_at'] : '') ?>"></label><p class="form-hint">La salle et le coach sélectionné doivent être disponibles ; les séances privées et autres cours du coach sont contrôlés.</p><div class="form-actions"><button class="primary">Ajouter au planning</button></div></form></details><details class="card form-card" <?= $error && ($_POST['action'] ?? '')==='room' ? 'open' : '' ?>><summary>+ Ajouter une salle</summary><form method="post" action="index.php?page=courses" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="room"><label>Nom de la salle *<input name="name" maxlength="100" required></label><div class="form-actions"><button class="primary">Créer la salle</button></div></form></details></div><?php endif; ?>
<?php if ($selectedCourse): ?><section class="card management-table"><div class="card-head"><div><h3>Inscriptions · <?= e($selectedCourse['title']) ?></h3><p><?= e(date('d/m/Y à H:i',strtotime($selectedCourse['starts_at']))) ?> · <?= e($selectedCourse['room']) ?></p></div><a class="text-link" href="index.php?page=courses">Fermer</a></div><?php if ($canWrite && $selectedCourse['status']==='scheduled' && $selectedCourse['starts_at']>date('Y-m-d H:i:s')): ?><form class="search-form" method="post" action="index.php?page=courses&amp;course=<?= (int)$selectedCourse['id'] ?>"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="book"><input type="hidden" name="course_id" value="<?= (int)$selectedCourse['id'] ?>"><label for="course-member">Membre</label><select id="course-member" class="input-select" name="member_id" required><option value="">Sélectionner un membre</option><?php foreach ($members as $m): ?><option value="<?= (int)$m['id'] ?>"><?= e($m['first_name'].' '.$m['last_name'].' · '.($m['card_number'] ?: 'Sans carte')) ?></option><?php endforeach; ?></select><button class="primary">Inscrire</button></form><p class="form-hint">Un abonnement actif est requis à la date du cours. Si le cours est complet, le membre rejoint la liste d’attente.</p><?php endif; ?><div class="table-scroll"><table><thead><tr><th>MEMBRE</th><th>STATUT</th><th>INSCRIPTION</th><?php if ($canWrite): ?><th>ACTION</th><?php endif; ?></tr></thead><tbody><?php foreach ($bookings as $b): ?><tr><td><?= e($b['first_name'].' '.$b['last_name']) ?></td><td><span class="status <?= $b['status']==='waiting' ? 'waiting-status' : '' ?>"><?= $b['status']==='confirmed' ? 'Confirmé' : 'En attente' ?></span></td><td><?= e(date('d/m/Y H:i',strtotime($b['created_at']))) ?></td><?php if ($canWrite): ?><td><?php if ($selectedCourse['status']==='scheduled' && $selectedCourse['starts_at']>date('Y-m-d H:i:s')): ?><form method="post" action="index.php?page=courses&amp;course=<?= (int)$selectedCourse['id'] ?>"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="cancel_booking"><input type="hidden" name="course_id" value="<?= (int)$selectedCourse['id'] ?>"><input type="hidden" name="booking_id" value="<?= (int)$b['id'] ?>"><button class="link-button" type="submit" data-confirm="Annuler cette réservation ?" onclick="return confirm('Annuler cette réservation ?')">Annuler</button></form><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?><?php if (!$bookings): ?><tr><td colspan="4" class="empty">Aucune inscription pour ce cours.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?>
<section class="card management-table"><div class="card-head"><div><h3>Planning à venir</h3><p>Jusqu’à 100 cours à partir d’aujourd’hui, fuseau de Tunis</p></div></div><div class="table-scroll"><table><thead><tr><th>COURS</th><th>DATE & HEURE</th><th>SALLE</th><th>COACH</th><th>PLACES</th><th>STATUT</th><th>ACTIONS</th></tr></thead><tbody><?php foreach ($courses as $c): ?><tr><td><strong><?= e($c['title']) ?></strong></td><td><?= e(date('d/m/Y H:i',strtotime($c['starts_at']))) ?> – <?= e(date('H:i',strtotime($c['ends_at']))) ?></td><td><?= e($c['room']) ?></td><td><?= e($c['coach'] ?: '—') ?></td><td><?= (int)$c['confirmed'] ?>/<?= (int)$c['capacity'] ?><?php if ($c['waiting']): ?> · <?= (int)$c['waiting'] ?> en attente<?php endif; ?></td><td><span class="status <?= $c['status']==='cancelled' ? 'expired' : '' ?>"><?= $c['status']==='cancelled' ? 'Annulé' : 'Planifié' ?></span></td><td><a class="text-link" href="index.php?page=courses&amp;course=<?= (int)$c['id'] ?>">Inscriptions</a><?php if ($canWrite && $c['status']==='scheduled' && $c['starts_at']>date('Y-m-d H:i:s')): ?><form method="post" action="index.php?page=courses" class="inline-action"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="cancel_course"><input type="hidden" name="course_id" value="<?= (int)$c['id'] ?>"><button class="link-button" data-confirm="Annuler ce cours et toutes ses réservations ?" onclick="return confirm('Annuler ce cours et toutes ses réservations ?')">Annuler le cours</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$courses): ?><tr><td colspan="7" class="empty">Aucun cours prévu. Créez une salle puis planifiez votre premier cours.</td></tr><?php endif; ?></tbody></table></div></section>
